[InitializeOnLoad]public static class FinalPNGCityDetails{
const string ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity",PrefabPath="Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab",Out="Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas";
static FinalPNGCityDetails(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalPNGCityDetails.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;var mode=File.ReadAllText("FinalPNGCityDetails.request").Trim();File.Delete("FinalPNGCityDetails.request");if(mode=="preview")Preview();else if(mode=="verify")Verify();else if(mode=="ceilingfix")CeilingFix();else if(mode=="extras")Extras();else if(mode=="parkingaudit")ParkingAudit();else if(mode=="parkingbuild")ParkingBuild();else Run(mode=="audit");}
class Data{public Vector3[] p,normal;public Vector4[] tangent;public Vector2[][] uv=new Vector2[8][];public Color[] colors;public int[] ids;}
class Road{public MeshFilter f;public Data d;public Vector3[] world;public Bounds bounds;public bool x;public float len,width;}
class Change{public MeshFilter f;public Mesh m;public Material[] mats;}
static Data Read(Mesh mesh){using(var all=MeshUtility.AcquireReadOnlyMeshData(mesh)){var d=all[0];var r=new Data();using(var a=new NativeArray<Vector3>(d.vertexCount,Allocator.Temp)){d.GetVertices(a);r.p=a.ToArray();if(d.HasVertexAttribute(VertexAttribute.Normal)){d.GetNormals(a);r.normal=a.ToArray();}}if(d.HasVertexAttribute(VertexAttribute.Tangent))using(var a=new NativeArray<Vector4>(d.vertexCount,Allocator.Temp)){d.GetTangents(a);r.tangent=a.ToArray();}if(d.HasVertexAttribute(VertexAttribute.Color))using(var a=new NativeArray<Color>(d.vertexCount,Allocator.Temp)){d.GetColors(a);r.colors=a.ToArray();}for(int channel=0;channel<8;channel++)if(d.HasVertexAttribute((VertexAttribute)((int)VertexAttribute.TexCoord0+channel)))using(var a=new NativeArray<Vector2>(d.vertexCount,Allocator.Temp)){d.GetUVs(channel,a);r.uv[channel]=a.ToArray();}var ids=new List<int>();for(int sub=0;sub<d.subMeshCount;sub++)using(var a=new NativeArray<int>(d.GetSubMesh(sub).indexCount,Allocator.Temp)){d.GetIndices(a,sub);ids.AddRange(a.ToArray());}r.ids=ids.ToArray();return r;}}
static bool Height(Road r,Vector3 point,out float y){var args=new object[]{r.world,r.d.ids,point,0f};bool ok=(bool)typeof(FinalPathwayRepair).GetMethod("Height",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,args);y=(float)args[3];return ok;}
static Mesh Copy(Data d,string name){var m=new Mesh{name=name,indexFormat=d.p.Length>65535?IndexFormat.UInt32:IndexFormat.UInt16};m.vertices=d.p;if(d.normal!=null)m.normals=d.normal;if(d.tangent!=null)m.tangents=d.tangent;if(d.colors!=null)m.colors=d.colors;for(int c=0;c<8;c++)if(d.uv[c]!=null)m.SetUVs(c,d.uv[c]);m.SetTriangles(d.ids,0);m.RecalculateBounds();return m;}
static Mesh Store(Mesh m,string name){string path=Out+"/Meshes/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(m,path);return m;}
static float Long(Road r,Vector3 p)=>r.x?p.x:p.z;static float Side(Road r,Vector3 p)=>r.x?p.z:p.x;
static bool SameGeometry(Data d,Mesh m){if(m.vertexCount!=d.p.Length||!m.vertices.SequenceEqual(d.p))return false;var indices=Enumerable.Range(0,m.subMeshCount).SelectMany(m.GetTriangles).ToArray();return indices.SequenceEqual(d.ids);}
static Vector2[] MapStraight(Road r,int tile,int rotate=0,bool junction=false){var result=new Vector2[r.world.Length];float lo=Long(r,r.bounds.min),hi=Long(r,r.bounds.max),a=Side(r,r.bounds.min),b=Side(r,r.bounds.max);float uvMin=r.d.uv[0].Min(v=>v.x),uvMax=r.d.uv[0].Max(v=>v.x);for(int i=0;i<result.Length;i++){var p=r.world[i];float u=junction?Mathf.InverseLerp(r.bounds.min.x,r.bounds.max.x,p.x):Mathf.InverseLerp(uvMin,uvMax,r.d.uv[0][i].x);float v=junction?Mathf.InverseLerp(r.bounds.min.z,r.bounds.max.z,p.z):Mathf.InverseLerp(lo,hi,Long(r,p));for(int k=0;k<rotate;k++){float old=u;u=1-v;v=old;}result[i]=new Vector2(tile*32+16+Mathf.Clamp(u,.00001f,.99999f),Mathf.Clamp(v,.00001f,.99999f));}return result;}
static Vector2[] MapCurve(GameObject root,Road r,int tile){object curve=typeof(FinalBridgeStructures).GetMethod("GetCurve",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{root,r.f.name});var rows=(System.Collections.IEnumerable)curve.GetType().GetField("rows").GetValue(curve);var points=new List<Vector3>();var distances=new List<float>();foreach(var row in rows){points.Add((Vector3)row.GetType().GetField("p").GetValue(row));distances.Add((float)row.GetType().GetField("s").GetValue(row));}var result=new Vector2[r.world.Length];float u0=r.d.uv[0].Min(v=>v.x),u1=r.d.uv[0].Max(v=>v.x);for(int i=0;i<result.Length;i++){var p=r.world[i];float closest=float.PositiveInfinity,s=0;for(int k=1;k<points.Count;k++){var delta=points[k]-points[k-1];float t=Mathf.Clamp01(Vector3.Dot(p-points[k-1],delta)/delta.sqrMagnitude);float dist=(p-Vector3.Lerp(points[k-1],points[k],t)).sqrMagnitude;if(dist<closest){closest=dist;s=Mathf.Lerp(distances[k-1],distances[k],t);}}result[i]=new Vector2(tile*32+16+Mathf.Clamp(Mathf.InverseLerp(u0,u1,r.d.uv[0][i].x),.00001f,.99999f),s/distances.Last());}return result;}
static Road[] Roads(GameObject root){return root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&f.sharedMesh.subMeshCount==1&&f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterial&&f.GetComponent<Renderer>().sharedMaterial.name=="Road Atlas").Select(f=>{var b=f.GetComponent<Renderer>().bounds;var d=Read(f.sharedMesh);return new Road{f=f,d=d,bounds=b,x=b.size.x>b.size.z,len=Mathf.Max(b.size.x,b.size.z),width=Mathf.Min(b.size.x,b.size.z),world=d.p.Select(f.transform.TransformPoint).ToArray()};}).ToArray();}
static int[] Approaches(Road j,Road[] roads){var b=j.bounds;var points=new[]{b.center+Vector3.forward*(b.size.z/2+8),b.center+Vector3.right*(b.size.x/2+8),b.center-Vector3.forward*(b.size.z/2+8),b.center-Vector3.right*(b.size.x/2+8)};return Enumerable.Range(0,4).Where(i=>roads.Any(r=>r!=j&&points[i].x>=r.bounds.min.x-.1f&&points[i].x<=r.bounds.max.x+.1f&&points[i].z>=r.bounds.min.z-.1f&&points[i].z<=r.bounds.max.z+.1f&&Height(r,points[i],out float y)&&Mathf.Abs(y-b.center.y)<.3f)).ToArray();}
static void Set(MeshFilter f,Mesh m,Material[] mats){f.sharedMesh=m;f.GetComponent<MeshRenderer>().sharedMaterials=mats;PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.GetComponent<MeshRenderer>());}
static void ConfigureTexture(){var importer=(TextureImporter)AssetImporter.GetAtPath(Out+"/City Road Detail Atlas.png");importer.textureType=TextureImporterType.Default;importer.sRGBTexture=true;importer.alphaSource=TextureImporterAlphaSource.FromInput;importer.alphaIsTransparency=true;importer.mipmapEnabled=true;importer.streamingMipmaps=true;importer.wrapMode=TextureWrapMode.Clamp;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=4;importer.maxTextureSize=4096;importer.textureCompression=TextureImporterCompression.Compressed;importer.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name="Android",overridden=true,maxTextureSize=4096,format=TextureImporterFormat.ASTC_6x6,compressionQuality=70});importer.SaveAndReimport();}
static Material Material(string name,Shader shader,Material source,Texture atlas){string path=Out+"/"+name+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old)return old;var m=source?new Material(source):new Material(shader);m.name=name;m.shader=shader;m.SetTexture("_MarkAtlas",atlas);m.enableInstancing=true;AssetDatabase.CreateAsset(m,path);return m;}
static void Run(bool audit){var log=new StringBuilder();bool saved=false;try{var scene=SceneManager.GetSceneByPath(ScenePath);if(!scene.isLoaded)throw new Exception("Open Gangstar Final Env.");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var roads=Roads(root);var allNames=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.gameObject.activeInHierarchy).ToArray();var bus=allNames.Where(r=>(r.name+" "+string.Join(" ",r.sharedMaterials.Where(m=>m).Select(m=>m.name))).ToLowerInvariant().Contains("bus")).ToArray();log.AppendLine("Road surfaces="+roads.Length+"; bus-related landmarks="+bus.Length);if(audit){foreach(var b in bus.Take(20))log.AppendLine("BUS "+b.name+" "+b.bounds);foreach(var r in roads.Where(r=>r.width>30&&r.width<45&&r.len<55&&r.bounds.size.y<.15f)){var a=Approaches(r,roads);log.AppendLine("JUNCTION "+r.f.name+" approaches="+string.Join(",",a));}File.WriteAllText("FinalEnvironmentRoadReview/PNGDetailAudit.txt",log.ToString());return;}
