foreach(var r in roads){int tile=-1,rotation=0;bool junction=false,curve=new[]{"polySurface537","polySurface538","polySurface539"}.Contains(r.f.name);if(curve){tile=13;curves++;}else if(r.width>30&&r.width<45&&r.len<55&&r.bounds.size.y<.15f&&(r.f.name.StartsWith("polySurface")||r.f.name.StartsWith("Line"))){var a=Approaches(r,roads);if(a.Length==4){tile=8+(junctions%4);junction=true;junctions++;}else if(a.Length==3){tile=12;int missing=Enumerable.Range(0,4).Except(a).Single();rotation=missing;junction=true;junctions++;}}else if(r.len>55&&r.width>24&&r.width<35){bool tunnel=r.f.name=="Continuous underpass roadway";float layer=Mathf.Floor(r.d.uv[0].Average(v=>v.x)/32);var busLandmark=bus.OrderBy(b=>b.bounds.SqrDistance(r.bounds.center)).FirstOrDefault();bool busNear=!tunnel&&busLandmark&&busLandmark.bounds.SqrDistance(r.bounds.center)<1600;if(busNear&&busBays<3){tile=1;float landmarkSide=r.x?busLandmark.bounds.center.z:busLandmark.bounds.center.x;int nearest=Enumerable.Range(0,r.world.Length).OrderBy(i=>Mathf.Abs(Side(r,r.world[i])-landmarkSide)).First();float uvMid=(r.d.uv[0].Min(v=>v.x)+r.d.uv[0].Max(v=>v.x))/2;rotation=r.d.uv[0][nearest].x>uvMid?2:0;busBays++;}else if(tunnel||new[]{"polySurface536","polySurface965"}.Contains(r.f.name))tile=4;else if(layer==2){tile=2;cycles++;}else if(fourWay.Any(j=>Vector3.Distance(j.bounds.center,r.bounds.center+(r.x?Vector3.right:Vector3.forward)*(r.len/2+20))<28)&&fourWay.Any(j=>Vector3.Distance(j.bounds.center,r.bounds.center-(r.x?Vector3.right:Vector3.forward)*(r.len/2+20))<28))tile=5;else if(new[]{"polySurface844","polySurface856"}.Contains(r.f.name))tile=3;else tile=0;straight++;}if(tile<0)continue;var m=Copy(r.d,"PNG_"+r.f.name+"_"+r.f.GetInstanceID());var map=curve?MapCurve(root,r,tile):MapStraight(r,tile,rotation,junction);float repeats=junction||tile==1?1:Mathf.Max(1,r.len/(tile==0?40:tile==2?60:tile==13?80:100));m.SetUVs(3,map.Select(v=>new Vector4(v.x,v.y*repeats,v.y,repeats)).ToList());if(!SameGeometry(r.d,m))throw new Exception("Road geometry changed: "+r.f.name);m=Store(m,m.name);changes.Add(new Change{f=r.f,m=m,mats=new[]{paint}});log.AppendLine("MARK "+r.f.name+" tile="+tile+" rotation="+rotation+" vertices/indices unchanged.");}
int ceilings=0;foreach(var module in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Sunken Underpass "))){var roof=module.GetComponentsInChildren<BoxCollider>(true).Single(c=>c.name=="Roof collision");var f=module.GetComponentsInChildren<MeshFilter>(true).Single(v=>v.name=="Concrete walls roof and curbs");var d=Read(f.sharedMesh);var world=d.p.Select(f.transform.TransformPoint).ToArray();var solid=new List<int>();var emissive=new List<int>();var uv=(Vector2[])d.uv[0].Clone();var b=roof.bounds;bool x=b.size.x>b.size.z;for(int k=0;k<d.ids.Length;k+=3){int a=d.ids[k],c=d.ids[k+1],e=d.ids[k+2];var n=Vector3.Cross(world[c]-world[a],world[e]-world[a]).normalized;var p=(world[a]+world[c]+world[e])/3;bool down=n.y<-.9f&&Mathf.Abs(p.y-b.min.y)<.025f&&p.x>=b.min.x-.01f&&p.x<=b.max.x+.01f&&p.z>=b.min.z-.01f&&p.z<=b.max.z+.01f;(down?emissive:solid).AddRange(new[]{a,c,e});if(down)foreach(int i in new[]{a,c,e})uv[i]=new Vector2((x?world[i].z:world[i].x)/8,(x?world[i].x:world[i].z)/8);}if(emissive.Count==0)throw new Exception("No ceiling underside found.");var mesh=Copy(d,"PNG_Ceiling_"+(ceilings+1));mesh.uv=uv;mesh.subMeshCount=2;mesh.SetTriangles(solid,0);mesh.SetTriangles(emissive,1);if(mesh.vertexCount!=d.p.Length||!mesh.vertices.SequenceEqual(d.p)||solid.Count+emissive.Count!=d.ids.Length)throw new Exception("Ceiling geometry changed.");mesh=Store(mesh,mesh.name);changes.Add(new Change{f=f,m=mesh,mats=new[]{f.GetComponent<MeshRenderer>().sharedMaterial,glow}});ceilings++;}
