static void Verify(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var atlas=AssetDatabase.LoadAssetAtPath<Texture2D>(Out+"/City Road Detail Atlas.png");int errors=0,roads=0;foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){var r=f.GetComponent<MeshRenderer>();if(!r)continue;foreach(var mat in r.sharedMaterials.Where(m=>m)){errors+=ShaderUtil.GetShaderMessages(mat.shader).Count(v=>v.severity.ToString()=="Error");if(mat.name.StartsWith("City PNG")&&(mat.HasProperty("_MarkAtlas")?mat.GetTexture("_MarkAtlas"):mat.GetTexture("_BaseMap"))!=atlas)throw new Exception("Different atlas bound.");}if(r.sharedMaterial&&r.sharedMaterial.name=="City PNG Markings"){var d=Read(f.sharedMesh);foreach(var col in f.GetComponents<MeshCollider>().Where(c=>c.sharedMesh)){var cd=Read(col.sharedMesh);if(!cd.p.SequenceEqual(d.p)||!cd.ids.SequenceEqual(d.ids))log.AppendLine("Existing separate collision mesh retained on "+f.name+"; render geometry was validated unchanged during application.");}roads++;}}
foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Sunken Underpass "))){var roof=t.GetComponentsInChildren<BoxCollider>(true).Single(c=>c.name=="Roof collision");var f=t.GetComponentsInChildren<MeshFilter>(true).Single(m=>m.name=="Concrete walls roof and curbs");var d=Read(f.sharedMesh);var world=d.p.Select(f.transform.TransformPoint).ToArray();log.AppendLine("CEILING "+t.name+" collider="+roof.bounds+" render="+f.GetComponent<Renderer>().bounds+" materials="+string.Join(",",f.GetComponent<Renderer>().sharedMaterials.Select(m=>m.name))+" indices="+f.sharedMesh.GetIndexCount(0)+","+f.sharedMesh.GetIndexCount(1)+" downMin="+world.Min(v=>v.y)+" upMax="+world.Max(v=>v.y));var renderer=f.GetComponent<MeshRenderer>();var lit=renderer.sharedMaterials.Last();var face=f.sharedMesh.GetTriangles(1).Select(i=>world[i]).ToArray();log.AppendLine("CEILING STATE enabled="+renderer.enabled+" active="+f.gameObject.activeInHierarchy+" forceOff="+renderer.forceRenderingOff+" batch="+renderer.isPartOfStaticBatch+" shader="+lit.shader.name+" supported="+lit.shader.isSupported+" plane="+string.Join(";",face.Select(v=>v.ToString())));var p=roof.bounds.center;bool x=roof.bounds.size.x>roof.bounds.size.z;var dir=x?Vector3.right:Vector3.forward;Capture(scene,p-dir*3-Vector3.up*2,p+Vector3.up*4,"PNG-Ceiling-Lookup-"+t.name.Replace(" ","_"));}
if(errors>0)throw new Exception("Shader errors="+errors);log.AppendLine("SUCCESS: marked road renderers verified="+roads+"; single PNG texture bound to all detail materials; shader errors=0.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/PNGDetailVerification.txt",log.ToString());}
static void CeilingFix(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var atlas=AssetDatabase.LoadAssetAtPath<Texture2D>(Out+"/City Road Detail Atlas.png");var glow=AssetDatabase.LoadAssetAtPath<Material>(Out+"/City PNG Ceiling Glow.mat");glow.shader=Shader.Find("Universal Render Pipeline/Lit");glow.shaderKeywords=new[]{"_EMISSION"};glow.SetTexture("_BaseMap",atlas);glow.SetTexture("_EmissionMap",atlas);glow.SetTextureScale("_BaseMap",new Vector2(.2385f,.2385f));glow.SetTextureOffset("_BaseMap",new Vector2(.75575f,.00575f));glow.SetColor("_BaseColor",Color.white);glow.SetColor("_EmissionColor",new Color(2.15f,2.15f,2.15f));glow.SetFloat("_Metallic",0);glow.SetFloat("_Smoothness",.2f);glow.SetFloat("_Cull",0);glow.SetFloat("_Surface",0);glow.SetFloat("_AlphaClip",0);glow.globalIlluminationFlags=MaterialGlobalIlluminationFlags.None;EditorUtility.SetDirty(glow);var changes=new List<Change>();int index=0;foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Sunken Underpass "))){var roof=t.GetComponentsInChildren<BoxCollider>(true).Single(c=>c.name=="Roof collision");var f=t.GetComponentsInChildren<MeshFilter>(true).Single(m=>m.name=="Concrete walls roof and curbs");var m=UnityEngine.Object.Instantiate(f.sharedMesh);m.name="PNG_Ceiling_Lit_"+(++index);var positions=m.vertices;var uv=m.uv;var b=roof.bounds;foreach(int i in m.GetTriangles(1).Distinct()){var p=f.transform.TransformPoint(positions[i]);uv[i]=new Vector2(Mathf.InverseLerp(b.min.x,b.max.x,p.x),Mathf.InverseLerp(b.min.z,b.max.z,p.z));}m.uv=uv;m=Store(m,m.name);changes.Add(new Change{f=f,m=m,mats=new[]{f.GetComponent<MeshRenderer>().sharedMaterials[0],glow}});}
