static void Extras(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var surfaces=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&f.sharedMesh.subMeshCount==1&&f.GetComponent<MeshRenderer>()&&f.GetComponent<MeshRenderer>().sharedMaterial&&new[]{"Road Atlas","City PNG Markings"}.Contains(f.GetComponent<MeshRenderer>().sharedMaterial.name)).Select(f=>{var d=Read(f.sharedMesh);var b=f.GetComponent<Renderer>().bounds;return new Road{f=f,d=d,bounds=b,world=d.p.Select(f.transform.TransformPoint).ToArray(),x=b.size.x>b.size.z,len=Mathf.Max(b.size.x,b.size.z),width=Mathf.Min(b.size.x,b.size.z)};}).ToArray();var landmarks=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.gameObject.activeInHierarchy&&!r.transform.IsChildOf(root.transform)).ToArray();var building=landmarks.Where(r=>r.bounds.size.y>4&&r.bounds.size.x>6&&r.bounds.size.z>6).ToArray();var bus=landmarks.FirstOrDefault(r=>string.Join(" ",r.sharedMaterials.Where(m=>m).Select(m=>m.name)).ToLowerInvariant().Contains("bus"));var changes=new List<Change>();var paint=AssetDatabase.LoadAssetAtPath<Material>(Out+"/City PNG Markings.mat");Road lot=null;Vector3 bay=Vector3.zero;float best=float.PositiveInfinity;
foreach(var r in surfaces.Where(r=>r.width>50&&r.len>65&&r.bounds.size.y<.15f)){for(float x=r.bounds.min.x+4;x<r.bounds.max.x-4;x+=5)for(float z=r.bounds.min.z+5;z<r.bounds.max.z-5;z+=5){var p=new Vector3(x,r.bounds.center.y,z);if(bus&&bus.bounds.SqrDistance(p)>1600)continue;if(building.Any(b=>x>b.bounds.min.x-2.2f&&x<b.bounds.max.x+2.2f&&z>b.bounds.min.z-3.3f&&z<b.bounds.max.z+3.3f))continue;bool clear=true;foreach(float dx in new[]{-2.1f,0,2.1f})foreach(float dz in new[]{-3.1f,0,3.1f}){var q=p+new Vector3(dx,0,dz);if(!Height(r,q,out float y)||Mathf.Abs(y-p.y)>.1f){clear=false;break;}if(Physics.CheckCapsule(q+Vector3.up*1.8f,q+Vector3.up*2.1f,1.2f,~0,QueryTriggerInteraction.Ignore)){clear=false;break;}}if(!clear)continue;float score=bus?bus.bounds.SqrDistance(p):building.Min(b=>b.bounds.SqrDistance(p));if(score<best){best=score;lot=r;bay=p;}}}
if(lot!=null){var m=Copy(lot.d,"PNG_Accessible_Forecourt_"+lot.f.name);m.SetUVs(3,lot.world.Select(p=>new Vector4((p.x-bay.x)/4.2f+.5f,(p.z-bay.z)/6.2f+.5f,6,-1)).ToList());if(!SameGeometry(lot.d,m))throw new Exception("Parking geometry changed.");m=Store(m,m.name);changes.Add(new Change{f=lot.f,m=m,mats=new[]{paint}});log.AppendLine("Accessible bay designated on existing clear paved forecourt "+lot.f.name+" at "+bay+"; 4.2m x 6.2m; no lane or building overlap.");}else log.AppendLine("No clear parking forecourt found; accessible bay remains available in atlas.");
var stopSigns=landmarks.Where(r=>(r.name+" "+string.Join(" ",r.sharedMaterials.Where(m=>m).Select(m=>m.name+" "+(m.HasProperty("_BaseMap")&&m.GetTexture("_BaseMap")?m.GetTexture("_BaseMap").name:"")))).ToLowerInvariant().Contains("stop")&&!r.name.ToLowerInvariant().Contains("bus")&&r.bounds.size.y>1).ToArray();int stops=0;foreach(var sign in stopSigns){var road=surfaces.Where(r=>r.len>55&&r.width>24&&r.width<35&&r.bounds.size.y<4&&!r.f.name.Contains("underpass")).OrderBy(r=>r.bounds.SqrDistance(sign.bounds.center)).FirstOrDefault();if(road==null||road.bounds.SqrDistance(sign.bounds.center)>625||changes.Any(c=>c.f==road.f))continue;var dir=road.x?Vector3.right:Vector3.forward;float direction=Vector3.Dot(sign.bounds.center-road.bounds.center,dir)>0?1:-1;dir*=direction;var right=Vector3.Cross(Vector3.up,dir);float coordinate=Long(road,sign.bounds.center);coordinate=Mathf.Clamp(coordinate,Long(road,road.bounds.min)+15,Long(road,road.bounds.max)-15);var center=road.x?new Vector3(coordinate,road.bounds.center.y,road.bounds.center.z):new Vector3(road.bounds.center.x,road.bounds.center.y,coordinate);center-=dir*10;center-=right*5;var m=Copy(road.d,"PNG_STOP_"+road.f.name);m.SetUVs(3,road.world.Select(p=>new Vector4(Vector3.Dot(p-center,right)/4+.5f,Vector3.Dot(p-center,dir)/3+.5f,16,-1)).ToList());if(!SameGeometry(road.d,m))throw new Exception("Stop geometry changed.");m=Store(m,m.name);changes.Add(new Change{f=road.f,m=m,mats=new[]{paint}});log.AppendLine("STOP paint before existing stop sign "+sign.name+" on "+road.f.name);if(++stops>=2)break;}
var prefab=PrefabUtility.LoadPrefabContents(PrefabPath);try{foreach(var change in changes){var path=AnimationUtility.CalculateTransformPath(change.f.transform,root.transform);Set(prefab.transform.Find(path).GetComponent<MeshFilter>(),change.m,change.mats);}if(changes.Count>0){PrefabUtility.SaveAsPrefabAsset(prefab,PrefabPath,out bool ok);if(!ok)throw new Exception("Prefab save failed.");}}finally{PrefabUtility.UnloadPrefabContents(prefab);}foreach(var change in changes)Set(change.f,change.m,change.mats);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);log.AppendLine("SUCCESS: specialist stamps="+changes.Count+"; same PNG atlas; geometry and colliders unchanged.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/PNGSpecialistPlacements.txt",log.ToString());}
static void ParkingBuild(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var shader=AssetDatabase.LoadAssetAtPath<Shader>(Out+"/Shaders/ParkingDetails.shader");if(ShaderUtil.GetShaderMessages(shader).Any(v=>v.severity.ToString()=="Error"))throw new Exception("Parking shader errors");var atlas=AssetDatabase.LoadAssetAtPath<Texture2D>(Out+"/City Road Detail Atlas.png");foreach(var f in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>new[]{"Parking_Material #47_0","Plane.003_0","Plane.003_002"}.Contains(f.name))){var d=Read(f.sharedMesh);var world=d.p.Select(f.transform.TransformPoint).ToArray();var r=f.GetComponent<MeshRenderer>();var b=r.bounds;Vector3 bay=f.name=="Plane.003_0"?new Vector3(440.55f,27.7f,160.66f):f.name=="Plane.003_002"?new Vector3(310.45f,27.82f,133.4f):new Vector3(b.min.x+9, b.min.y,-310);bool building=f.name.StartsWith("Parking_Material");if(building){float best=float.PositiveInfinity;for(int k=0;k<d.ids.Length;k+=3){var a=world[d.ids[k]];var c=world[d.ids[k+1]];var e=world[d.ids[k+2]];if(Vector3.Cross(c-a,e-a).normalized.y<.9f)continue;var p=(a+c+e)/3;if(p.y>b.min.y+3)continue;float score=(new Vector2(p.x-bay.x,p.z-bay.z)).sqrMagnitude;if(score<best){best=score;bay.y=p.y;}}if(float.IsInfinity(best))throw new Exception("No parking floor found");bay=new Vector3(696f,40.63231f,-325.0f);var candidates=new List<string>();for(int k=0;k<d.ids.Length;k+=3){var a=world[d.ids[k]];var c=world[d.ids[k+1]];var e=world[d.ids[k+2]];if(Vector3.Cross(c-a,e-a).normalized.y>.9f&&a.y<b.min.y+4)candidates.Add(a+";"+c+";"+e);}for(int k=0;k<d.ids.Length;k+=3){var a=world[d.ids[k]];var c=world[d.ids[k+1]];var e=world[d.ids[k+2]];var v0=new Vector2(c.x-a.x,c.z-a.z);var v1=new Vector2(e.x-a.x,e.z-a.z);var q=new Vector2(bay.x-a.x,bay.z-a.z);float det=v0.x*v1.y-v1.x*v0.y;if(Mathf.Abs(det)<.001f)continue;float u=(q.x*v1.y-v1.x*q.y)/det;float v=(v0.x*q.y-q.x*v0.y)/det;if(u>=0&&v>=0&&u+v<=1)log.AppendLine("SURFACE y="+(a.y+u*(c.y-a.y)+v*(e.y-a.y))+" normal="+Vector3.Cross(c-a,e-a).normalized.y);} }else{var rr=new Road{f=f,d=d,world=world,bounds=b};if(Height(rr,bay,out float y))bay.y=y;}var mesh=Copy(d,"PNG_Parking_"+f.name.Replace(" ","_").Replace("#",""));float width=building?2.5f:2.35f,length=building?4.0f:4.7f;mesh.SetUVs(3,world.Select(p=>{float u=building?(p.z-bay.z)/width+.5f:f.name=="Plane.003_002"?(p.z-bay.z)/width+.5f:(p.x-bay.x)/width+.5f;float v=building?(p.x-bay.x)/length+.5f:f.name=="Plane.003_002"?(bay.x-p.x)/length+.5f:(p.z-bay.z)/length+.5f;return new Vector4(u,v,6,building?-1-Mathf.Abs(p.y-bay.y)*10:-1);}).ToList());if(building){var uv4=new List<Vector4>();mesh.GetUVs(3,uv4);log.AppendLine("UV sample "+string.Join(";",Enumerable.Range(0,d.p.Length).Where(i=>Mathf.Abs(world[i].y-bay.y)<.01f).Take(10).Select(i=>world[i]+"="+uv4[i])));}if(!SameGeometry(d,mesh))throw new Exception("Parking geometry changed");mesh=Store(mesh,mesh.name);var mat=Material("City PNG Parking "+(building?"Building":"Cafe"),shader,r.sharedMaterial,atlas);if(building){mat.SetVector("_ParkingBay",new Vector4(bay.x,bay.y,bay.z,1));mat.SetVector("_ParkingSize",new Vector4(width,length,0,1));EditorUtility.SetDirty(mat);}var original=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(f.gameObject);var destination=Out+"/PNG "+f.name+".prefab";var pref=PrefabUtility.LoadPrefabContents(original);try{var pf=pref.GetComponentsInChildren<MeshFilter>(true).Single(v=>v.name==f.name);Set(pf,mesh,new[]{mat});PrefabUtility.SaveAsPrefabAsset(pref,destination,out bool ok);if(!ok)throw new Exception("Parking prefab save failed");}finally{PrefabUtility.UnloadPrefabContents(pref);}Set(f,mesh,new[]{mat});log.AppendLine(f.name+" accessible bay="+bay+"; prefab="+destination+"; geometry/colliders unchanged");var hidden=building?scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(v=>v!=r&&v.enabled).ToArray():new Renderer[0];foreach(var h in hidden)h.enabled=false;Capture(scene,bay+Vector3.up*(building?2.3f:13)+ (building?Vector3.zero:Vector3.zero),bay,"PNG-Parking-"+f.name);foreach(var h in hidden)h.enabled=true;}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed");log.AppendLine("SUCCESS: three parking targets, same PNG atlas, reusable scene-specific prefabs, no added geometry.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/PNGUserParkingBuild.txt",log.ToString());}
static void ParkingAudit(){var log=new StringBuilder();var scene=SceneManager.GetSceneByPath(ScenePath);foreach(var f in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>new[]{"Parking_Material #47_0","Plane.003_0","Plane.003_002"}.Contains(f.name))){var r=f.GetComponent<MeshRenderer>();Capture(scene,r.bounds.center+Vector3.up*90,r.bounds.center,"Parking-Before-"+f.name);if(f.name.StartsWith("Parking_Material"))Capture(scene,r.bounds.center+new Vector3(-75,25,0),r.bounds.center-Vector3.up*7,"Parking-Building-Side");log.AppendLine("PARKING "+f.name+" path="+AnimationUtility.CalculateTransformPath(f.transform,null)+" bounds="+(r?r.bounds.ToString():"no renderer")+" submeshes="+f.sharedMesh.subMeshCount+" scale="+f.transform.lossyScale+" materials="+(r?string.Join(",",r.sharedMaterials.Select(m=>m.name+"/"+m.shader.name)):"none")+" prefab="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(f.gameObject));}File.WriteAllText("FinalEnvironmentRoadReview/PNGUserParkingAudit.txt",log.ToString());}
static void Preview(){var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var marked=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterial&&f.GetComponent<Renderer>().sharedMaterial.name=="City PNG Markings").ToArray();int index=0;foreach(var f in marked.Where(f=>f.GetComponent<Renderer>().bounds.size.y<.15f&&Mathf.Max(f.GetComponent<Renderer>().bounds.size.x,f.GetComponent<Renderer>().bounds.size.z)<55).Take(4)){var p=f.GetComponent<Renderer>().bounds.center;Capture(scene,p+Vector3.up*48,p,"PNG-Junction-"+(++index));}var road=marked.FirstOrDefault(f=>f.name=="polySurface809")??marked.First();var b=road.GetComponent<Renderer>().bounds;Capture(scene,b.center+Vector3.up*38+Vector3.forward*20,b.center,"PNG-Road-Markings");foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Sunken Underpass "))){var roof=t.GetComponentsInChildren<BoxCollider>(true).Single(c=>c.name=="Roof collision");var p=roof.bounds.center;bool x=roof.bounds.size.x>roof.bounds.size.z;var dir=x?Vector3.right:Vector3.forward;Capture(scene,p-dir*14-Vector3.up*3,p+dir*5-Vector3.up*.4f,"PNG-Ceiling-"+t.name.Replace(" ","_"));}}
static void Capture(Scene scene,Vector3 p,Vector3 target,string name){var go=new GameObject("PNG detail preview camera"){hideFlags=HideFlags.HideAndDontSave};SceneManager.MoveGameObjectToScene(go,scene);var c=go.AddComponent<Camera>();c.enabled=false;c.nearClipPlane=.1f;c.farClipPlane=5000;c.fieldOfView=62;c.transform.SetPositionAndRotation(p,Quaternion.LookRotation(target-p,Mathf.Abs((target-p).normalized.y)>.99f?Vector3.forward:Vector3.up));var rt=RenderTexture.GetTemporary(1400,1000,24);var old=RenderTexture.active;bool async=ShaderUtil.allowAsyncCompilation;try{ShaderUtil.allowAsyncCompilation=false;c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(1400,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1400,1000),0,0);tex.Apply();File.WriteAllBytes("FinalEnvironmentRoadReview/"+name+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{ShaderUtil.allowAsyncCompilation=async;RenderTexture.active=old;c.targetTexture=null;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(go);}}
